DO $wrap$ BEGIN EXECUTE $s$CREATE OR REPLACE VIEW public.workspace_members_safe AS
SELECT 
  wm.id,
  wm.workspace_id,
  wm.user_id,
  wm.role,
  wm.name,
  wm.invited_at,
  wm.accepted_at,
  CASE 
    WHEN wm.user_id = auth.uid() THEN wm.email
    WHEN EXISTS (
      SELECT 1 FROM public.workspaces w 
      WHERE w.id = wm.workspace_id AND w.owner_id = auth.uid()
    ) THEN wm.email
    ELSE CONCAT(LEFT(wm.email, 2), '***@', SPLIT_PART(wm.email, '@', 2))
  END AS email
FROM public.workspace_members wm$s$; EXCEPTION WHEN duplicate_object OR duplicate_table OR duplicate_column OR duplicate_schema OR duplicate_alias OR duplicate_function THEN NULL; WHEN others THEN RAISE NOTICE 'pulado (%): %', SQLSTATE, SQLERRM; END $wrap$;
