DO $wrap$ BEGIN EXECUTE $s$CREATE VIEW public.workspace_members_safe
WITH (security_invoker = true)
AS
SELECT 
  wm.id,
  wm.workspace_id,
  wm.user_id,
  wm.role,
  wm.accepted_at,
  wm.invited_at,
  CASE 
    WHEN wm.user_id = auth.uid() THEN wm.email
    WHEN wm.email IS NOT NULL AND length(wm.email) > 0 THEN 
      left(split_part(wm.email, '@', 1), 2) || '***@' || split_part(wm.email, '@', 2)
    ELSE NULL
  END AS email,
  CASE 
    WHEN wm.user_id = auth.uid() THEN wm.name
    ELSE coalesce(left(wm.name, 1) || '***', 'Membro')
  END AS name
FROM public.workspace_members wm$s$; EXCEPTION WHEN duplicate_object OR duplicate_table OR duplicate_column OR duplicate_schema OR duplicate_alias OR duplicate_function THEN NULL; WHEN others THEN RAISE NOTICE 'pulado (%): %', SQLSTATE, SQLERRM; END $wrap$;
