DO $wrap$ BEGIN EXECUTE $s$CREATE OR REPLACE VIEW public.slack_dlq_stats
WITH (security_invoker = true) AS
SELECT
  workspace_id,
  COUNT(*) FILTER (WHERE resolved_at IS NULL AND attempts < 5) AS pending,
  COUNT(*) FILTER (WHERE resolved_at IS NULL AND attempts >= 5) AS dead,
  COUNT(*) FILTER (WHERE resolved_at IS NOT NULL) AS resolved,
  MAX(created_at) FILTER (WHERE resolved_at IS NULL) AS oldest_pending_at,
  MAX(attempts) FILTER (WHERE resolved_at IS NULL) AS max_attempts
FROM public.slack_dispatch_dlq
GROUP BY workspace_id$s$; EXCEPTION WHEN duplicate_object OR duplicate_table OR duplicate_column OR duplicate_schema OR duplicate_alias OR duplicate_function THEN NULL; WHEN others THEN RAISE NOTICE 'pulado (%): %', SQLSTATE, SQLERRM; END $wrap$;
