DO $wrap$ BEGIN EXECUTE $s$CREATE OR REPLACE VIEW public.slack_dispatch_health AS
SELECT
  workspace_id,
  COALESCE(SUM((metadata->>'successes')::int), 0)::bigint AS successes,
  COALESCE(SUM((metadata->>'failures')::int), 0)::bigint AS failures,
  COUNT(*)::bigint AS total_dispatches,
  MAX(created_at) AS last_dispatch_at
FROM public.audit_events
WHERE event_type = 'slack_integration'
  AND action = 'alert_dispatched'
  AND created_at > now() - INTERVAL '24 hours'
GROUP BY workspace_id$s$; EXCEPTION WHEN duplicate_object OR duplicate_table OR duplicate_column OR duplicate_schema OR duplicate_alias OR duplicate_function THEN NULL; WHEN others THEN RAISE NOTICE 'pulado (%): %', SQLSTATE, SQLERRM; END $wrap$;
